import math
def priority(task, state, c=1.0, R=1000.0, L=1000.0, eps=0.001):
    est = max(task.estimated_runtime, 1e-6)
    if task.due <= state.now:
        return -L - est
    slack = task.due - state.now - est
    scale = max(state.mean_est, est, 1e-6)
    if slack < c * scale:
        return R - slack - eps * est
    return -est

import math
def priority(task, state, q=8.0, p=1.0, L=1000.0, eps=0.001):
    est = max(task.estimated_runtime, 1e-6)
    if task.due <= state.now:
        return -L - est
    pressure = state.queue_work / max(state.capacity * max(state.mean_est, 1e-6), 1e-6)
    if state.queue_len >= q or pressure >= p:
        return -(task.due - state.now) - eps * est
