def priority(task, state, overdue_penalty=5.0, age=1.0, guard_c=3.0, premium_shift=1.0, tardiness_penalty=0.5):
    now = state.now
    est = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, 1e-6)
    wait = max(0.0, now - task.release)
    due = task.due
    if task.tenant == 'premium':
        due -= premium_shift * mean
    p = -max(due, now + est)
    if due < now:
        p -= overdue_penalty
        wait_ratio = wait / est
        if wait_ratio > guard_c:
            p += overdue_penalty * (1.0 + wait_ratio - guard_c)
    else:
        if now + est > due:
            p -= tardiness_penalty * (now + est - due) / mean
    return p + age * wait / est

