import math
def priority(task, state, m=2.0, c=1.0, d=0.5, u=1e12):
    est = max(task.estimated_runtime, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    slack = task.due - state.now - est
    ratio = slack / est
    base = tier / est
    if task.tenant == 'premium':
        if ratio < -d:
            return -u + base
        if ratio <= c:
            return u + (c - ratio) + base
    return base

import math
def priority(task, state, m=3.0, a=5.0, k=1.0, late=1.0, c=0.0, alpha=1.0,
             beta=0.0, q=1.0, floor=0.05):
    est = max(task.estimated_runtime, 1e-6)
    mem = max(task.resource_need, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    typ = q if task.task_type == 'code' else 1.0
    scale = max(state.mean_est, est, 1e-6)
    slack = task.due - state.now - est

    x = (c * scale - slack) / max(k * scale, 1e-6)
    if x > 50.0:
        risk = 1.0
    elif x < -50.0:
        risk = 0.0
    else:
        risk = 1.0 / (1.0 + math.exp(-x))

    y = (slack + late * scale) / max(k * scale, 1e-6)
    if y > 50.0:
        keep = 1.0
    elif y < -50.0:
        keep = 0.0
    else:
        keep = 1.0 / (1.0 + math.exp(-y))

    base = tier * typ / ((est ** alpha) * (mem ** beta))
    return base * (floor + a * risk * keep)

