import math
def priority(task, state, k=4.0, m=1.5, q=1.0, width=0.5, late_scale=2.0, mem_pow=0.2, guard=1.5):
    est = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, 1e-6)
    now = state.now
    slack = task.due - est - now

    pressure = state.queue_work / max(state.capacity, 1e-6)
    cong = pressure / mean
    y = (cong - q) / max(width, 1e-6)
    if y < -50.0:
        blend = 0.0
    elif y > 50.0:
        blend = 1.0
    else:
        blend = 1.0 / (1.0 + math.exp(-y))

    base = task.weight / est
    atc = base * math.exp(-max(0.0, slack) / (max(k, 1e-6) * mean))

    if slack >= 0.0:
        edf_urgency = 1.0 / (1.0 + slack / mean)
    else:
        edf_urgency = 1.0
    edf = base * edf_urgency

    score = (1.0 - blend) * atc + blend * edf

    if slack < 0.0:
        score *= math.exp(slack / (max(late_scale, 1e-6) * mean))

    if task.tenant == 'premium' and 0.0 <= (task.due - now) < guard * est:
        score *= m

    if slack > guard * mean:
        score *= 1.0 / (max(task.resource_need, 1e-6) ** max(mem_pow, 0.0))

    return score

import math
def priority(task, state, k=4.0, b=0.4, m=1.7, guard=1.5, c=1.2, late_scale=2.0, mem_pow=0.25):
    est = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, 1e-6)
    now = state.now
    wait = now - task.release
    time_left = task.due - now
    slack = time_left - est
    age = 1.0 + b * wait / est

    if slack >= 0.0:
        urg = math.exp(-slack / (max(k, 1e-6) * mean))
    else:
        if time_left >= 0.0:
            urg = 1.0 / (1.0 + (-slack) / mean)
        else:
            urg = 1.0

    base = task.weight / est * age * urg

    if time_left > 0.0 and slack >= 0.0 and wait > c * slack:
        base *= (1.0 + guard)

    if task.tenant == 'premium' and time_left > -mean:
        base *= m

    if time_left < 0.0:
        base *= math.exp(time_left / (max(late_scale, 1e-6) * mean))

    if slack > c * mean:
        base *= 1.0 / (max(task.resource_need, 1e-6) ** max(mem_pow, 0.0))

    return base

