import math
def priority(task, state, q=5.0, k=2.0, a=1.5, m=2.0, doomed=0.1, eps=1e-6):
    est = max(task.estimated_runtime, eps)
    slack = task.due - state.now - est
    tier = m if task.tenant == 'premium' else 1.0
    base = tier / est
    if slack < 0.0:
        return doomed * base
    if state.queue_len < q:
        return base
    scale = max(k * max(state.mean_est, est), eps)
    urg = math.exp(-slack / scale)
    return base * (1.0 + a * urg)

def priority(task, state, a=1.0, b=0.5, m=2.0, eps=1e-6):
    est = max(task.estimated_runtime, eps)
    slack = task.due - state.now - est
    tier = m if task.tenant == 'premium' else 1.0
    base = tier / est
    if slack < 0.0:
        return base / (1.0 + a * (-slack) / est)
    risk = 1.0 / (1.0 + max(0.0, slack) / est)
    wait = max(0.0, state.now - task.release)
    wait_ratio = wait / est
    age = wait_ratio / (1.0 + wait_ratio)
    return base * (1.0 + a * risk + b * age)

def priority(task, state, m=2.0, horizon=2.0, urgent=1e6, a=2.0, b=0.5, c=0.2, d=0.1, mem_w=0.1, tie=1e-3, doomed=0.02, eps=1e-6):
    est = max(task.estimated_runtime, eps)
    now = state.now
    tier = m if task.tenant == 'premium' else 1.0
    wait = max(0.0, now - task.release)
    mean = max(state.mean_est, est, eps)
    age = wait / max(wait + mean, eps)
    if task.due <= now:
        return doomed * tier / max(est, eps)
    rem = task.due - now
    slack = rem - est
    window = max(horizon * max(mean, est), eps)
    risk = 1.0 / max(1.0 + max(slack, 0.0) / window, eps)
    edf = 1.0 / max(1.0 + rem / window, eps)
    mem_ratio = task.resource_need / max(state.free, eps)
    mem_score = 1.0 / max(1.0 + mem_ratio, eps)
    if slack < window or rem < window:
        return urgent + a * risk + b * edf + c * age + d * mem_score + tie * tier / max(est, eps)
    return tier * (1.0 + c * age) / max(est + mem_w * task.resource_need, eps)

def priority(task, state, m=2.0, urgent=1e6, horizon=2.0, a=4.0, b=0.5, c=0.2, mem_w=0.2, risk_w=0.01, tie=1e-3, doomed=0.02, eps=1e-6):
    est = max(task.estimated_runtime, eps)
    now = state.now
    tier = m if task.tenant == 'premium' else 1.0
    wait = max(0.0, now - task.release)
    mean = max(state.mean_est, est, eps)
    age = wait / max(wait + mean, eps)
    if task.due <= now:
        return doomed * tier / max(est, eps)
    rem = task.due - now
    crit = rem / max(est, eps)
    risk = 1.0 / max(1.0 + crit, eps)
    mem_ratio = task.resource_need / max(state.free, eps)
    mem_score = 1.0 / max(1.0 + mem_ratio, eps)
    urgent_condition = (rem < horizon * (est + mean)) or (crit < horizon)
    if urgent_condition:
        return urgent + a * risk + b * age + c * mem_score + tie * tier / max(est, eps)
    return tier * (1.0 + b * age) * (1.0 + risk_w * risk) * mem_score / max(est, eps)

